// AmbientSoundManager FLAGS property bits (read by AmbientSoundManager_Init 0x494a02 and Update 0x494170)
enum AmbientSoundFlags {
    AMBS_CINE_UPDATE = 0x1,  // ScnObject flags |= 0x20: keeps updating (and playing) during cinematics
    AMBS_POSITIONAL = 0x2,  // playFlags |= SNDF_POSITIONAL
    AMBS_POSITIONAL_HORIZONTAL = 0x4,  // if bit1 clear: playFlags |= POSITIONAL|DIST_HORIZONTAL. Also, in box mode the vertical falloff factor is skipped
    AMBS_LOOP = 0x8,  // playFlags |= SNDF_LOOP: replayed when found stopped (checked every other update), no repeat timer
    AMBS_LINEAR_FALLOFF = 0x10,  // volume = VOLUME*(1 - dist/MAXDIST), with SNDF_NO_ATTENUATION. Unused in retail data (max FLAGS is 13)
};

// u16 at Animator+0x22 (obj+0x62)
enum AnimFlags {
    ANIM_F_PLAYING = 0x1,  // Anim_Advance runs only if set; cleared at end of non-looping anim
    ANIM_F_LOOP = 0x2,  // set from SetAnim mode bit 0
    ANIM_F_ALT_WRAP = 0x4,  // initial value has it (5); selects buffer-swap wrap path
    ANIM_F_FINISHED = 0x8,  // set when frame wraps to 0 / anim missing; cleared each advancing step
};

// u16 control word of each packed entry in an AnimKey (also stored in AnimJointPose.channels)
enum AnimKeyChannel {
    ANIMKEY_JOINT_MASK = 0x003f,  // joint index 0-63 (not checked against the joint count)
    ANIMKEY_ROT_X = 0x0040,  // rot[0] present
    ANIMKEY_ROT_Y = 0x0080,  // rot[1] present
    ANIMKEY_ROT_Z = 0x0100,  // rot[2] present
    ANIMKEY_POS_X = 0x0200,  // pos[0] present
    ANIMKEY_POS_Y = 0x0400,  // pos[1] present
    ANIMKEY_POS_Z = 0x0800,  // pos[2] present
    ANIMKEY_SCALE_X = 0x1000,  // scale[0] present
    ANIMKEY_SCALE_Y = 0x2000,  // scale[1] present
    ANIMKEY_SCALE_Z = 0x4000,  // scale[2] present
    ANIMKEY_8BIT = 0x8000,  // values are bytes (angle s8*2PI/128, pos s8, scale u8/128), payload re-aligned to 2 bytes afterwards
};

// 4th arg of Anim_Start 0x550196 (src/objects/animation.cpp)
enum AnimSetMode {
    ANIM_SET_LOOP = 0x1,  // loop
    ANIM_SET_BLEND = 0x2,  // start at frame 0 blending from current pose
    ANIM_SET_OPTIONAL = 0x4,  // no error log if animId missing
};

// state field of Anvil
enum AnvilState {
    ANVIL_ST_WAIT = 0x0,  // Update case 0: waits for `dropping` and the end of the anim, then starts ANVIL2 and goes to 2 (inferred)
    ANVIL_ST_LIFT = 0x1,  // Update case 1: on anim end starts STAND0, hides the anvil and goes to 3 (inferred)
    ANVIL_ST_HOLD = 0x2,  // Update case 2: holds 2000 ms after the drop, then releases the scripted camera and goes to 1 (inferred)
    ANVIL_ST_DONE = 0x3,  // entered hidden from 1; Update has no case 3 (inferred)
};

// g_langMask 0x57910A, the single-bit language selector produced by App_GetLanguageMask 0x4035EF and consumed by every TextRes_LoadString call. The switch is on GetUserDefaultLangID() & 0xFF (0x4035fe), not PRIMARYLANGID (& 0x3FF); the values below are that low byte. The constants are LANGMASK_*: src/sdk/win32.h's LANG_* are the SDK's LANGIDs (App_GetLanguageMask switches on those).
enum AppLanguageMask {
    LANGMASK_ENGLISH = 0x01,  // LANGID & 0xFF == 9.
    LANGMASK_FRENCH = 0x02,  // LANGID & 0xFF == 0xC, and the fallback for every unlisted language.
    LANGMASK_GERMAN = 0x04,  // LANGID & 0xFF == 7.
    LANGMASK_DUTCH = 0x08,  // LANGID & 0xFF == 0x13.
    LANGMASK_SPANISH = 0x10,  // LANGID & 0xFF == 0xA.
    LANGMASK_ITALIAN = 0x20,  // LANGID & 0xFF == 0x10.
    LANGMASK_PORTUGUESE = 0x40,  // LANGID & 0xFF == 0x16; the language InputDevice_GetObjectName 0x4071B0 has its hard-coded space-bar fix for.
};

// AttachLink +7 as read by Instance_CalcWorldMatrix and written by Instance_DrawAnimParts
enum AttachLinkFlags {
    ATTACH_F_MATRIX_VALID = 0x01,  // set when the parent's draw publishes the matrix; without it the child is marked invisible
    ATTACH_F_PARENT_RENDERED = 0x02,  // parent processed this frame: Scenaric_RenderAll clears 0x01|0x02 (& 0xFC) on every active link, then renders the parent of any link without 0x02; Scn_RenderIfVisible sets it (| 2) on its child links.
    ATTACH_F_ROOT_ROTATION = 0x04,  // publish the root part M[0] rotation with part M[partIndex] translation
    ATTACH_F_LOCAL_OFFSET = 0x08,  // child translation = link matrix applied to localOffset*8
    ATTACH_F_EXTRA_ROTATION = 0x10,  // multiply by RotXYZ(link rot) when publishing
    ATTACH_F_WORLD_OFFSET = 0x20,  // add worldOffset*8 to the child translation
};

