// Dragon +0x270 (SetState table 0x446b53, UpdateState table 0x445e5e). Flying set = Dragon_IsFlying.
enum DragonState {
    DRAGON_ST_IDLE = 0x0,  // Anim 7 loop, faces the Wolf. Also the landing point of msg 0x75 and of 0x23, whatever the altitude.
    DRAGON_ST_FIRE = 0x1,  // Wolf msg 0x35 (burn, WOLF_ST_BURNT) if the Wolf is not dead; anim 0xd; -> 0.
    DRAGON_ST_INHALE = 0x2,  // Anim 0xc, faces the Wolf. At the end -> 1 if IsWolfInFireReach, else 0.
    DRAGON_ST_FLY_FIRE = 0x3,  // Airborne burn: msg 0x35, anim 0x19; -> 0x13.
    DRAGON_ST_FLY_INHALE = 0x4,  // Airborne inhale, anim 0x15. At the end -> 3 if in reach, else 0x13.
    DRAGON_ST_BACK_AWAY = 0x5,  // Anim 1 once, faces the Wolf, retreats at 300 u/s (ZONE-leashed); -> 0. Entered when a non-running Wolf is within 300.
    DRAGON_ST_FLY_BACK_AWAY = 0x6,  // Airborne version, anim 0x16; -> 0x13.
    DRAGON_ST_CHASE = 0x7,  // Walk (anim 1, 600 u/s) or run (anim 2, 1200 u/s, dust) toward the Wolf while he is within 1280. Advances only while dist >= 350.
    DRAGON_ST_SKID1 = 0x8,  // Anim 0xe. Per-frame halving skid after a run; -> 9 when the skid ends OR the anim finishes.
    DRAGON_ST_SKID2 = 0x9,  // Anim 0xf; the same exit test -> 0xa.
    DRAGON_ST_SKID3 = 0xa,  // Anim 0x10; -> 0 when the skid has ended AND the anim finished.
    DRAGON_ST_IDLE_PICK = 0xb,  // Transient: Rand_Bounded(5) == 0 -> 0xc, else 0xf.
    DRAGON_ST_IDLE_A1 = 0xc,  // Faces the Wolf once, idleLoopsLeft = Rand(3)+1, anim 4 loop; one loop -> 0xd.
    DRAGON_ST_IDLE_A2 = 0xd,  // Anim 5 loop, idleLoopsLeft loops -> 0xe.
    DRAGON_ST_IDLE_A3 = 0xe,  // Anim 6 loop, one loop -> 0.
    DRAGON_ST_IDLE_B = 0xf,  // idleLoopsLeft = Rand(12)+1 loops of anim 7 -> 0.
    DRAGON_ST_FLY_WAIT = 0x10,  // Hover (anim 0x16 loop) facing the Wolf while he is outside ZONE; his x/z in ZONE -> 0x13.
    DRAGON_ST_TAKEOFF = 0x11,  // flyHeight = 0, anim 0x12; -> 0x12.
    DRAGON_ST_RISE = 0x12,  // Anim 0x11, climbs up to 160; -> 0x14 if flyToRockZone, else 0x13.
    DRAGON_ST_FLY_CHASE = 0x13,  // Anim 8/9, faces the Wolf, hover-chases at 600 u/s (ZONE-leashed).
    DRAGON_ST_FLY_TO_ROCKZONE = 0x14,  // Faces rockZoneTarget and flies there at 1800 u/s, ignoring ZONE; dragon x/z in ROCKZONE -> 0x13.
    DRAGON_ST_FLY_TO_SPHERE = 0x15,  // Accepted time-machine call while flying: faces and approaches sphereTarget, ignoring ZONE. Left only by msg 0x39/0x75.
    DRAGON_ST_LAND = 0x16,  // Anim 0xa; -> 0x17.
    DRAGON_ST_DESCEND = 0x17,  // Anim 0x14; descends until flyHeight < 0 or a non-Wolf floor contact; -> 0x18.
    DRAGON_ST_TOUCHDOWN = 0x18,  // SnapToGround(1), anim 0xb; -> 0.
    DRAGON_ST_WAIT_FIRST_CONTACT = 0x19,  // Initial state: anim 7, faces the Wolf; his x/z in BOXFIRSTCONTACT -> 0x1a. Messages refused.
    DRAGON_ST_CINE_FIRST_CONTACT = 0x1a,  // Cine_Start(CINEFIRSTCONTACT, FLAGFIRSTCONTACT); when g_cinePlayer.active == 0 -> SnapToGround, 0. Messages refused.
    DRAGON_ST_WALK_TO_SPHERE = 0x1b,  // Accepted call while grounded: faces sphereTarget, anim 1, ZONE-leashed approach. Unreachable with the Lvl-09 layout.
    DRAGON_ST_TIMEWARP = 0x1c,  // msg 0x39 while grounded: box collision off, anim 0x17; -> 0x1e.
    DRAGON_ST_FLY_TIMEWARP = 0x1d,  // msg 0x39 while flying: anim 0x1a; -> 0x1e.
    DRAGON_ST_IN_TRANSIT = 0x1e,  // Inert until msg 0x3a.
    DRAGON_ST_ARRIVE = 0x1f,  // msg 0x3a: collision on, SetPosition(arrival), anim 0x18; -> 0x20.
    DRAGON_ST_CINE_CHRONOBALL = 0x20,  // Cine_Start(CINECHRONOBALL, FLAGCHRONOBALL); when the cine is inactive -> 0x25. Messages refused.
    DRAGON_ST_TAKEOFF_TO_SPHERE = 0x21,  // Call accepted during 0x11: keeps the take-off anim; -> 0x22.
    DRAGON_ST_RISE_TO_SPHERE = 0x22,  // Anim 0x11, climbs; -> 0x15.
    DRAGON_ST_WAIT_PRESENT = 0x23,  // Call refused while grounded: anim 7, frozen (no AI) until TimeMachine_IsInPresent(Wolf); then 0.
    DRAGON_ST_FLY_WAIT_PRESENT = 0x24,  // Call refused while flying: anim 0x16, frozen until the Wolf is in the present; then savedState.
    DRAGON_ST_GONE = 0x25,  // After the CHRONOBALL cine: hidden (0x800), no box collision, no Update, all messages refused. Permanent, survives Reset.
    DRAGON_ST_NONE = 0x26,  // Sentinel written by Init before SetState(0x19).
};

