// Bits of HeapBlock.sizeFlags (u32 at block+0)
enum HeapBlockFlags {
    HEAPBLK_PREV_FREE = 0x1,  // The block before this one is free; its size is in the u32 at header-4 (footer). Set by writeFree on the following block, cleared by CarveBlock's decrement.
    HEAPBLK_FREE = 0x2,  // This block is on the free list.
    HEAPBLK_SIZE_MASK = 0x0ffffffc,  // Block size in bytes including the 8-byte header; 28 bits, so at most 256 MB.
    HEAPBLK_ALIGN_MASK = 0xf0000000,  // (log2(align)-2) << 28, written only by Heap_AllocAligned; never read.
};

// Constants of the engine heap
enum HeapConst {
    HEAP_ALLOC_MAGIC = 0x98765432,  // Written at block+4 on allocation (0x54df1f, 0x54e2d8); the only two occurrences in the image. Never compared.
    HEAP_MIN_SPLIT = 0x18,  // A free block is split only if at least 24 bytes would remain; otherwise the caller gets the whole block.
    HEAP_SENTINEL_SIZE = 0x10,  // Size of the permanent end block.
    HEAP_HEADER_SIZE = 0x8,  // Header bytes before the user pointer; also the minimum payload size.
    HEAP_SMALLPOOL_THRESHOLD = 0x100000,  // Heap_Init sets up small pools only when the arena is larger than this.
};

