// slot of an InputMgr binding table (InputMgr.keyTable / padTable, 16 {device, button} pairs; verified in InputMgr::Poll and BindMenuKey). Slots 0..11 are the PS1 buttons Poll turns into the active-low pad word, slots 12..15 the menu directions (keyboard only, also the keyboard's axis keys). Not the g_inputMap slots (InputMapSlot)
enum InputBindSlot {
    INPUT_BIND_TRIANGLE = 0x0,  // Poll clears PAD_TRIANGLE
    INPUT_BIND_CIRCLE = 0x1,  // Poll clears PAD_CIRCLE
    INPUT_BIND_CROSS = 0x2,  // Poll clears PAD_CROSS
    INPUT_BIND_SQUARE = 0x3,  // Poll clears PAD_SQUARE
    INPUT_BIND_L1 = 0x4,  // Poll clears PAD_L1
    INPUT_BIND_R1 = 0x5,  // Poll clears PAD_R1
    INPUT_BIND_L2 = 0x6,  // Poll clears PAD_L2
    INPUT_BIND_R2 = 0x7,  // Poll clears PAD_R2
    INPUT_BIND_SELECT = 0x8,  // Poll clears PAD_SELECT
    INPUT_BIND_START = 0x9,  // Poll clears PAD_START
    INPUT_BIND_L3 = 0xa,  // Poll clears PAD_L3
    INPUT_BIND_R3 = 0xb,  // Poll clears PAD_R3
    INPUT_BIND_MENU_UP = 0xc,  // menu up: BindMenuKey also makes it the keyboard's Y- axis key (KB_AXIS_Y_NEG)
    INPUT_BIND_MENU_RIGHT = 0xd,  // menu right: the keyboard's X+ axis key (KB_AXIS_X_POS)
    INPUT_BIND_MENU_DOWN = 0xe,  // menu down: the keyboard's Y+ axis key (KB_AXIS_Y_POS)
    INPUT_BIND_MENU_LEFT = 0xf,  // menu left: the keyboard's X- axis key (KB_AXIS_X_NEG)
};

