// Messages handled by Mine_HandleMessage 0x4d505c, GroundMine_HandleMessage 0x4d5f98 and DefusableMine_HandleMessage 0x4d7347 (ids are per receiver)
enum MineMsg {
    // MSG_KILL = 0x0  (already defined in enum ScnMsg)  blast: arg 0 in state 2 -> countdown (0.1665 s, not cancellable); chain reaction
    // MSG_USE = 0x1  (already defined in enum ScnMsg)  DefusableMine: start defusal (-> state 6), no state check
    // MSG_QUERY_ACTION = 0x2  (already defined in enum ScnMsg)  DefusableMine: 4 CTX_PICKUP in state 0 (Wolf/Robot); 0xC CTX_DEFUSE in state 2 while dormant (Wolf only)
    // MSG_PICKUP = 0x4  (already defined in enum ScnMsg)  DefusableMine: attach to the sender joint, state 0
    // MSG_DROP = 0x5  (already defined in enum ScnMsg)  DefusableMine: arg {Vec3s pos; u16 flags}; flags & 1 re-arms (state 1)
    // MSG_SEESAW_TOUCH = 0xb  (already defined in enum ScnMsg)  GroundMine: start falling unless attached; returns 0
    // MSG_LAUNCH = 0xc  (already defined in enum ScnMsg)  DefusableMine: explode now (state 4)
    // MSG_FREEZE = 0xe  (already defined in enum ScnMsg)  DefusableMine: from the Wolf, aborts a defusal in state 7/8 back to armed state 2
    // MSG_CINE_END = 0x13  (already defined in enum ScnMsg)  base: savedPos = pos if in world
    // MSG_QUERY_HELD_ACTION = 0x17  (already defined in enum ScnMsg)  DefusableMine: 2 HELD_THROWABLE
    // MSG_RIDER_ADD = 0x18  (already defined in enum ScnMsg)  GroundMine: mover = sender if empty (Magnet); returns 1 always
    // MSG_RIDER_REMOVE = 0x19  (already defined in enum ScnMsg)  GroundMine: clear mover if sender; returns 1
    // MSG_LANDED = 0x25  (already defined in enum ScnMsg)  GroundMine: same as 0xb
    // MSG_DETECTOR_PING = 0x2f  (already defined in enum ScnMsg)  MineDetector cone search: non-zero = detectable. Mines return 1 (GroundMine only in proximity mode); GoldenCoins return 1 and reveal themselves
    // MSG_MAGNET_QUERY = 0x51  (already defined in enum ScnMsg)  GroundMine: 1 = magnetic (proximity mode only). Sent by Magnet_Update 0x4d235e
    // MSG_MAGNET_PULL = 0x53  (already defined in enum ScnMsg)  GroundMine: forced-trigger bit 4 (arg {magnet, reply}); returns 0
    // MSG_CHECKPOINT_ROLLBACK = 0x55  (already defined in enum ScnMsg)  DefusableMine: vtable Reset
    MSG_DETECTOR_RAY = 0x5a,  // GroundMine: returns the distance along the sender's facing to open hazard (GroundMine_RayToHazard), INT_MAX = none
};

// Mine +0xa6 (Mine_SetState 0x4d4dbe, table 0x4d5048; DefusableMine_Update table 0x4d7327)
enum MineState {
    MINE_ST_SAFE = 0,  // DefusableMine: defused or carried (pickup prompt); no base action
    MINE_ST_REARMING = 1,  // deadline = now + 5 s; DefusableMine returns to 2 once the deadline has passed AND it is in the dormant half
    MINE_ST_ARMED = 2,  // armed: proximity/region check (subclass); msg 0 arg 0 starts a countdown
    MINE_ST_COUNTDOWN = 3,  // deadline = now + 0x2aa (0.1665 s); GroundMine proximity trigger overrides it with fuseDelay and can cancel back to 2
    MINE_ST_EXPLODING = 4,  // exploded model + anim 0, shadow hidden, MSG_KILL broadcasts (300 any class, 550 Rocks), camera shake
    MINE_ST_EXPLODED = 5,  // explosion anim finished. GroundMine stays here until Reset; DefusableMine waits 20 s, resets, goes to 1
    DM_ST_DEFUSE_BEGIN = 6,  // DefusableMine: MSG_USE received; next update -> 7
    DM_ST_PLAYBACK = 7,  // DefusableMine: shows the code one symbol per step (Ralph frozen via msg 0xe)
    DM_ST_INPUT = 8,  // DefusableMine: the player repeats the code on the beat; success -> 0, any miss -> 4
};

// language block of a .MLT file: Mlt_MapLanguageToBlock 0x548d76 turns the config language (GameLanguage) into one of these in place, and Load_MLT_ParseBank 0x548980 skips to it; other values pass through unchanged
enum MltBlock {
    MLT_BLOCK_ENGLISH = 0x1,  // read for config language 0 (GAME_LANG_ENGLISH)
    MLT_BLOCK_SPANISH = 0x2,  // read for config language 1 (GAME_LANG_SPANISH)
    MLT_BLOCK_ITALIAN = 0x3,  // read for config language 2 (GAME_LANG_ITALIAN)
    MLT_BLOCK_BRAZILIAN = 0x6,  // read for config language 3 (GAME_LANG_BRAZILIAN); the only non-consecutive entry
};

// mapping from the configuration language index (byte at *(void**)0x57b80c + 0xBB) to the MLT block index that Load_MLT's string-bank builder 0x548980 skips to, performed by 0x548D76. Values outside 0..3 pass through unchanged
enum MltLanguageBlock {
    MLT_CFG0_BLOCK1 = 0x00,  // config language 0 reads MLT block 1
    MLT_CFG1_BLOCK2 = 0x01,  // config language 1 reads MLT block 2
    MLT_CFG2_BLOCK3 = 0x02,  // config language 2 reads MLT block 3
    MLT_CFG3_BLOCK6 = 0x03,  // config language 3 reads MLT block 6 - the only non-consecutive entry, and the one that can walk past the end of the buffer
};

