// Bit layout of the pad word tested by Pad_MenuPressed/Held/Repeat, which take the INVERTED mask (Pad_MenuPressed(0xBFFF) tests bit 0x4000). Recovered from the masks used across this module; it is exactly the PlayStation digital-pad layout, which the PC port kept. Bits 0x2000 CIRCLE and 0x8000 SQUARE are confirmed in game by the level-skip cheat input.
enum PadButton {
    PAD_SELECT = 0x0001,  // opens/closes the map (Game_Frame_2 tests 0xFFFE)
    PAD_L3 = 0x2,  // InputMgr::Poll binding 10 clears 0xfffd; standard PS1 pad bit 1 (the named bits already follow the PS1 layout: SELECT 0, UP 4 .. LEFT 7, TRIANGLE 12 .. SQUARE 15) (inferred)
    PAD_R3 = 0x4,  // binding 11 clears 0xfffb; PS1 pad bit 2 (inferred)
    PAD_START = 0x8,  // binding 9 clears 0xfff7; PS1 pad bit 3; ScnControllable::ReadPad PRESSED(pad, 9) -> WolfActionBits 4 (inferred)
    PAD_UP = 0x0010,  // mask 0xFFEF
    PAD_RIGHT = 0x0020,  // mask 0xFFDF
    PAD_DOWN = 0x0040,  // mask 0xFFBF
    PAD_LEFT = 0x0080,  // mask 0xFF7F
    PAD_L2 = 0x100,  // binding 6 clears 0xfeff; PS1 pad bit 8 (inferred)
    PAD_R2 = 0x200,  // binding 7 clears 0xfdff; PS1 pad bit 9 (inferred)
    PAD_L1 = 0x400,  // Input_ApplyControlConfig passes 0xfbff as the 6th remap in every preset; PS1 pad bit 10 (inferred)
    PAD_R1 = 0x800,  // 0xf7ff 5th remap; PS1 pad bit 11 (inferred)
    PAD_TRIANGLE = 0x1000,  // cancel/back; mask 0xEFFF
    PAD_CIRCLE = 0x2000,  // mask 0xDFFF. Confirmed in game: the 5th/6th press of the level-skip code
    PAD_CROSS = 0x4000,  // confirm/validate; mask 0xBFFF
    PAD_SQUARE = 0x8000,  // mask 0x7FFF. Confirmed in game: the 1st/2nd/4th press of the level-skip code
    PAD_ALL_RELEASED = 0xffff,  // the raw active-low pad word with no button down (Cheat_CheckSequence tests cur/prev != 0xffff)
};

// the port argument of Pad::Open 0x55f0a8: the PlayStation libpad port id (port << 4); Input_Init opens g_pad on port 1 and g_pad2 on port 2. The PC Pad::Open ignores it
enum PadPort {
    PAD_PORT_1 = 0x00,  // the first controller port (g_pad) (inferred from the libpad convention)
    PAD_PORT_2 = 0x10,  // the second controller port (g_pad2) (inferred from the libpad convention)
};

// PS1 controller type id at Pad+0x57/+0x58 and in the high nibble of frame byte 1
enum PadType {
    PADTYPE_NONE = 0x0,  // Pad::ResetState / PadRec: padType = 0 (no device) (inferred)
    PADTYPE_MOUSE = 1,  // PS1 mouse (id 0x12). Only the debug free camera tests it (type nibble of Pad+0x2b == 1 at 0x552900), then reads +0x2e/+0x2f as signed deltas. Whether the PC input layer ever reports it is not checked.
    PADTYPE_DIGITAL = 4,  // InputMgr_IsDeviceDigital(0) == 1 (keyboard / digital device); PS1 id 0x41
    PADTYPE_ANALOG = 7,  // analog device; PS1 DualShock id 0x73. Enables the Pad_AnalogToStick paths
};

