// RenderPoly field +0x04, the dispatch value of PolyBatcher_SubmitPoly 0x415c80 and of the state-flag slot accessors 0x416d04 / 0x416d73 / 0x416df2. Extends the existing RenderPoly.type comment with the type-0 line case.
enum RenderPolyType {
    RPOLY_LINE = 0,  // line-list primitive; appended to the 4000-vertex buffer at PolyBatcher+0x58, drawn as D3DPT_LINELIST with FVF 0xc4 and state flags +0x60 (0x121). Only the flush path draws it.
    RPOLY_OPAQUE = 1,  // untextured opaque triangle; 0x48 bytes appended to PolyBatcher+0x2c, drawn as TRIANGLELIST with FVF 0xc4 and state flags +0x34 (0x120)
    RPOLY_BLEND = 2,  // untextured alpha-blended triangle; always deferred to the depth-sorted list and drawn with state flags +0x50 (RSF_BLEND_ALPHA)
    RPOLY_ADD = 3,  // untextured additive triangle; always deferred and drawn with state flags +0x54 (RSF_BLEND_ADD)
    RPOLY_TEXTURED_BASE = 4,  // values >= 4 are a texture page index plus 4; bit 0x8000 is masked off with & 0xFFFF7FFF at every use. Index < immediateTexCount goes into that page's own batch (FVF 0x1c4), otherwise it is deferred and depth-sorted.
    RPOLY_F_8000 = 0x8000,  // RenderPoly::InitFromBsTexGouraud sets type |= 0x8000; every user masks it with & 0xffff7fff (RenderPolyType doc)
};

// Bitmask passed to Render_SetStateFlags (0x4155F0) and Render_ClearStateFlags (0x4159B0). Each bit maps to one or more IDirect3DDevice7 SetRenderState / SetTextureStageState calls. Values decoded from the D3DRENDERSTATETYPE numbering (SRCBLEND=19, DESTBLEND=20, CULLMODE=22, ALPHAREF=24, ALPHAFUNC=25, DITHERENABLE=26, ALPHABLENDENABLE=27, FOGENABLE=28, SPECULARENABLE=29, LIGHTING=137, COLORVERTEX=141, CLIPPLANEENABLE=152).
enum RenderStateFlags {
    RSF_ANTIALIAS = 0x00001,  // ANTIALIAS = SORTDEPENDENT(2); cleared to NONE(0)
    RSF_BLEND_ALPHA = 0x00002,  // ALPHABLENDENABLE=1, SRCBLEND=INVSRCALPHA(6), DESTBLEND=SRCALPHA(5) — note the inverted-alpha convention
    RSF_BLEND_ADD = 0x00004,  // ALPHABLENDENABLE=1, SRCBLEND=INVSRCALPHA(6), DESTBLEND=ONE(2) — additive
    RSF_ALPHATEST = 0x00008,  // ALPHATESTENABLE=1, ALPHAREF=8, ALPHAFUNC=LESSEQUAL(4)
    RSF_CLIPPLANE = 0x00010,  // CLIPPLANEENABLE=1 (clip plane 0)
    RSF_DITHER = 0x00020,  // DITHERENABLE=1
    RSF_LIGHTING = 0x00040,  // LIGHTING=1
    RSF_SPECULAR = 0x00080,  // SPECULARENABLE=1
    RSF_COLORVERTEX = 0x00100,  // COLORVERTEX=1
    RSF_CULL_CW = 0x00200,  // CULLMODE=CW(2); cleared to NONE(1)
    RSF_CULL_CCW = 0x00400,  // CULLMODE=CCW(3); cleared to NONE(1)
    RSF_ZTEST = 0x00800,  // ZENABLE=1
    RSF_ZWRITE_OFF = 0x01000,  // ZWRITEENABLE=0 (then ZENABLE=1 if the call succeeded); the clear path writes ZWRITEENABLE=1
    RSF_ZWRITE_ON = 0x02000,  // ZWRITEENABLE=1 (then ZENABLE=1 if the call succeeded); the clear path writes ZWRITEENABLE=0
    RSF_TEXTURED = 0x04000,  // stage 0: TEXCOORDINDEX(0xb)=0, COLORARG1(2)=TEXTURE(2), COLORARG2(3)=DIFFUSE(0), COLOROP(1)=MODULATE(4). When clear, the set path instead writes COLORARG1=DIFFUSE, COLOROP=SELECTARG1(2) (untextured). The clear path writes COLOROP=DISABLE. Verified in 0x4155f0; the first call is TEXCOORDINDEX, not ALPHAARG2 (stage state 6).
    RSF_FILTER_LINEAR = 0x08000,  // stage 0: MAGFILTER(0x10)=MINFILTER(0x11)=LINEAR(2); cleared to POINT(1). Verified in 0x4155f0 and 0x4159b0; ADDRESSU/ADDRESSV (stage states 13/14) are never written.
    RSF_FOG = 0x10000,  // FOGENABLE=1
};

