// ScnObject::Collide_ResolveMove's flags argument (0x50e6b7), on top of the CollideClass bits of the contacts to slide along (flags & COLL_WALL, then flags & COLL_FLOOR; 0 sweeps once and never slides). Read from its code (src/engine/scenaric.cpp): the sweep query is CQ_STATIC | CQ_OBJECTS plus what these bits change, never the argument itself (verified)
enum ResolveMoveFlags {
    RESOLVE_SLIDE_ALL = 0x07,  // COLL_FLOOR | COLL_WALL | COLL_FLOOR_EDGE, the usual mask (Wolf steps, Gossamer, Catapult, WoodenLift): slide along floors and walls (the slide never tests the COLL_FLOOR_EDGE bit: floor edges are stepped onto or block) (verified)
    RESOLVE_KEEP_Y = 0x08,  // sliding keeps the vertical part of the displacement: only x and z are projected off the contact planes (verified)
    RESOLVE_ASK_MOVER = 0x20,  // the sweeps add CQ_ASK_MOVER (0x10) and CQ_IGNORE_SKIPBOX (0x20) (verified)
    RESOLVE_NO_STATIC = 0x40,  // the sweeps drop CQ_STATIC (no static triangles) and add CQ_IGNORE_SKIPBOX (0x20) (verified)
};

// Box.flags of a Wolf RESTRICTIONBOX zone (Wolf::restrictions)
enum RestrictBoxFlags {
    RESTRICT_F_NO_RUN = 0x40000000,  // Wolf::FilterInput: a restriction box with 0x40000000 removes the run bit (inputMask &= ~4)
};

// u32 Robot+0x2dc
enum RobotFlags {
    ROBOT_F_CONTROLLED = 0x1,  // player input goes to the robot (Robot_IsControllable); set by TakeControl and by msg 0xF
    ROBOT_F_TOUCHING_MOVABLE = 0x2,  // per frame: Robot_Move contact.movableObj; blocks put-down and dormancy
    ROBOT_F_ON_OBJECT = 0x4,  // per frame: standing on a scenaric object; suppresses the camera ledge probe
    ROBOT_F_TRAPPED = 0x8,  // caught in WolfTrap +0x290
    ROBOT_F_STRUGGLE = 0x10,  // msg 0x40 from the trap; state 0x18 → 0x19
    ROBOT_F_DRIVEN = 0x20,  // robot owns the camera request; msg 0x3681 (read by WoodenLift, CameraRestriction and LightSpot)
    ROBOT_F_DEAD = 0x40,  // ignores msg 0, 0x3F, 0xB/0x25 and the death-zone test until Reset
    ROBOT_F_SMOKE_PHASE = 0x80,  // toggled by smokeFlickerTimer; smoke spawns only when set
    ROBOT_F_AXIS_LOCK_A = 0x100,  // per frame (msg 0x44 arg 0): heading snapped to 0x400/0xC00
    ROBOT_F_AXIS_LOCK_B = 0x200,  // per frame (msg 0x44 arg 1): heading snapped to 0/0x800
    ROBOT_F_POWERED_ON = 0x400,  // power-on anim (state 3) already played; cleared by Reset
    ROBOT_F_IN_SHADOW = 0x800,  // inside a g_shadowBoxes zone this frame; tint 0xC00
    ROBOT_F_BURNT = 0x1000,  // tint 0x1000 (black); set by msg 0 kill
    ROBOT_F_DEATH_FALLS = 0x2000,  // death anim keeps gravity and ends in SetState(1) (msg 0 kill, water, most death boxes)
};

// Messages handled by Robot_HandleMessage 0x460b93 (sender, id, arg)
enum RobotMsg {
    // MSG_KILL = 0x0  (already defined in enum ScnMsg)  Sam + EJECTTRAJ → eject (state 0x11); arg 0 from others → die (0x10 for FireBall, else 0xF); always returns 1
    // MSG_QUERY_ACTION = 0x2  (already defined in enum ScnMsg)  Wolf within the vertical window → 2 (CTX_LIFT)
    // MSG_PICKUP = 0x4  (already defined in enum ScnMsg)  Magnet: hang 75 below joint; else carried by Ralph (state 2)
    // MSG_DROP = 0x5  (already defined in enum ScnMsg)  detach, face away from dropper, SetPosition unless flag bit 1, state 1
    // MSG_QUERY_NEAREST_TARGET = 0x6  (already defined in enum ScnMsg)  forwarded to heldObject
    // MSG_SEESAW_TOUCH = 0xb  (already defined in enum ScnMsg)  with 0x25: end of launch/throw → state 1, or 7 if controlled and in 0x15
    // MSG_LAUNCH = 0xc  (already defined in enum ScnMsg)  state 0x15
    // MSG_FREEZE = 0xe  (already defined in enum ScnMsg)  suspend control (third party) or release to the Wolf
    // MSG_UNFREEZE = 0xf  (already defined in enum ScnMsg)  CONTROLLED |= 1, suspender = 0 (no check)
    // MSG_CARRY_ANIM = 0x10  (already defined in enum ScnMsg)  arg 1 → anim 0, args 0/2..6 → anim 1
    // MSG_QUERY_HELD_ACTION = 0x17  (already defined in enum ScnMsg)  → 2 (HELD_THROWABLE)
    // MSG_RIDER_ADD = 0x18  (already defined in enum ScnMsg)  ScnControllable_AddMoveModifier
    // MSG_RIDER_REMOVE = 0x19  (already defined in enum ScnMsg)  ScnControllable_RemoveMoveModifier
    // MSG_LANDED = 0x25  (already defined in enum ScnMsg)  same handler as 0xB
    // MSG_TRAP_STATE = 0x33  (already defined in enum ScnMsg)  arg 0 (trap released): clear TRAPPED/STRUGGLE; arg 1 ignored
    // MSG_REMOTE_SWITCH = 0x3f  (already defined in enum ScnMsg)  from RemoteControl: arg 1 take control, arg 0 release
    // MSG_STRUGGLE = 0x40  (already defined in enum ScnMsg)  WolfTrap relays each Action press: STRUGGLE flag
    // MSG_AXIS_LOCK = 0x44  (already defined in enum ScnMsg)  per-frame heading snap
    MSG_GRABBER_CAMERA = 0x49,  // from Wolf_UpdateCamera: Robot_UpdateCamera(pad)
    // MSG_QUERY_CONTROLLED = 0x4c  (already defined in enum ScnMsg)  → CONTROLLED bit
    // MSG_MAGNET_QUERY = 0x51  (already defined in enum ScnMsg)  → 1 (meaning unknown) -- the magnet update 0x4d235e pulls only candidates that answer nonzero; the Robot always answers 1 (it is magnetic)
    MSG_DRAW_PROMPT = 0x6b,  // draw HUD prompts while DRIVEN
    MSG_ROBOT_IS_ACTIVE = 0x3680,  // → state flag 8
    // MSG_ROBOT_IS_DRIVEN = 0x3681  (already defined in enum ScnMsg)  → robotFlags & 0x20
    MSG_ROBOT_IS_EJECTED = 0x3682,  // → state in 0x11..0x14 (queried by LightSpot 0x4f6ecd)
};

