// class-registry flag bits: g_scnClassRegistry[classId].classFlags (u32 at 0x6cffe4 + classId*0x10)
enum ScnClassFlags {
    SCN_CF_INTERACTABLE = 0x001,  // considered by ScnControllable_ScanInteractables
    SCN_CF_SHEEP_ATTRACTOR = 0x2,  // Sheep_AttractorScoreCB 0x4784ca sends msg 2 only to classes with it
    SCN_CF_CARRIER = 0x004,  // recorded as ContactInfo.carrierObj; blocks Wolf put-down on top
    SCN_CF_08 = 0x8,  // Scenaric_RegisterClass_2 passes 0x9 for the Daffy classes; no reader in the census (inferred)
    SCN_CF_SEESAW_SNAP = 0x10,  // seesaw_Update translates the body by the plank gap when it did not handle msg 0xb (Wolf, Sheep, Rock, box, items…)
    SCN_CF_SNAP_TO_SUPPORT = 0x20,  // pulled onto its support even when above it (ground snap). Set on 12 classes: Dynamite, Salad, Perfume, Bush, DefusableMine, 3 costumes, HoneyPot, Key, InflatableSheep, GoldenCoins. Does NOT mean carryable: the Bush is not carried in game (Ralph gets inside it and is hidden from Sam). Name inferred
    SCN_CF_GROUND_PROVIDER = 0x40,  // ObjGrid_QueryGroundY 0x472380 sends msg 0xD (MSG_GROUND_QUERY) only to these classes: seesaw, Rock, Wooden Lift, WoodenPlatForm, Raft, Catapult, Snowball, SnowyGround, IceGround, WheelDummy, RollingCarpet, RCarpetMobile, CrumblyGround, Jail, Train, FloatingBox, Case, CrumblyPlat. Name inferred from use
    SCN_CF_INTERACT_ANY_FACING = 0x080,  // facing-angle test skipped
    SCN_CF_COMPONENT_ITEM = 0x100,  // Set only on Magnet (66) and FishingRod (67), the two parts of the composite rods. No reader of bit 0x100 found among the 34 direct reads of 0x6cffe4 (some masks are in registers), so the name is inferred
    SCN_CF_COMPOSITE_ITEM = 0x200,  // composite inventory item
    SCN_CF_INVENTORY_ITEM = 0x400,  // the class appears as a row on the map/inventory screen; Map_InitObject selects classes with 0x400 set and 0x200 clear, and Map_Open / Map_AcquireItem test it before converting an object to a list row
    SCN_CF_SHEEP_ANCHORABLE = 0x800,  // Sheep only; matches SheepMsg 0x2e MSG_SET_ANCHOR (seesaw walk-to-end)
    SCN_CF_IGNORED_BY_BUTTONS = 0x1000,  // SensibleButton_Update skips these objects. reg_arg3 has it for SensibleButton(24), CannonBall(95), DancingGhost(127), PrayingGhost(130), Train(135)
};

// u16 at ScnObject+0x3a
enum ScnObjFlags {
    SCN_OF_MUTE_ANIM_SOUND = 0x0002,  // animation sound events not played (0x50d540); set by Wolf/Sheep in some states
    SCN_OF_HIDDEN2 = 0x0004,  // with 0x800: not rendered, ignored by proximity queries (mask 0x804; Scn_RenderIfVisible 0x55ffe3 skips the object). Set by ObjectManager_SetObjectsActive 0x4da187 on deactivate: keepUpdating == 0 gives flags = (flags & 0xbfff) | 0x2004; keepUpdating != 0 sets flags = 4 outright. Was also spelled SCNOBJ_SKIP_RENDER_4
    SCN_OF_KEPT = 0x0008,  // inventory item committed at checkpoint (survives restart)
    SCN_OF_NO_PLANE_CULL = 0x0010,  // the near/frustum view-plane test in Scn_RenderIfVisible / RenderAll is skipped (the distance test still applies). Was also spelled SCNOBJ_IGNORE_CULL_PLANE
    SCN_OF_CINE_UPDATE = 0x0020,  // keeps updating when tagged 0x80 in cinematic mode
    SCN_OF_NO_DIST_CULL = 0x0040,  // exempt from the 9000000 dist2 cut in tinted render / several class updates
    SCN_OF_IN_CINE_BOX = 0x0080,  // tagged by cinematic box scan 0x561f50
    SCN_OF_IN_WORLD = 0x0100,  // linked in grid + g_scnActive
    SCN_OF_CUSTOM_COLLIDE = 0x0200,  // collision sweeps call vtable +0x0c
    SCN_OF_NO_BOX_COLLIDE = 0x0400,  // box test skipped (unless query flag 0x20); interact scan uses point distance
    SCN_OF_HIDDEN = 0x0800,  // not rendered and skipped by proximity queries; this is the bit cinematic opcodes 4/5 toggle (Cine_OpToggleObjectFlag 0x562fc0 = cinematic HIDE/SHOW). Was also spelled SCNOBJ_HIDDEN
    SCN_OF_INITIALISED = 0x1000,  // initial value set by both Inits; no reader found (inferred)
    SCN_OF_NEVER_UPDATE = 0x2000,  // Update never called
    SCN_OF_ALWAYS_UPDATE = 0x4000,  // ignores the 3000-unit camera radius
};

// Argument of an inlined update-mode setter that unoptimised MSVC compiles as a 4-way jump table on a constant (seen at 0x50d89e table 0x50d93b and 0x50a094 table 0x50a1d9). It edits ScnObject.flags (+0x3a).
enum ScnUpdateMode {
    SCN_UPD_NORMAL = 0,  // clear 0x4000 and 0x2000: updated only within the 3000-unit camera radius
    SCN_UPD_ALWAYS = 1,  // set 0x4000, clear 0x2000 (Wooden Lift uses this)
    SCN_UPD_NEVER = 2,  // clear 0x4000, set 0x2000 (generic fallback logic objects)
    SCN_UPD_CINE = 3,  // flags |= 0x20 (keeps updating in cinematic mode)
};

