// g_selectMenuState 0x6de5d5 = g_map.state; read with 0x5428a0, written with 0x542893. Values 1..6 are all driven by PER-FRAME counters, never by g_dt.
enum SelectMenuState {
    SEL_CLOSED = 0,  // map not open; the game runs normally
    SEL_OPEN_WIPE = 1,  // curtain bars growing +7 px per frame from top and bottom (0x542759); at height > 0x7F calls Map_Open. ~19 frames
    SEL_OPEN_HOLD = 2,  // phaseCounter counts down from 0xF, one per frame, fading the map in; ~15 frames
    SEL_INTERACTIVE = 3,  // the player can move the cursor, use, combine, split and read help
    SEL_CLOSE_HOLD = 4,  // phaseCounter counts up to 0xF fading the map out; ~15 frames
    SEL_CLOSE_WIPE = 5,  // closeCounter 0..10; at 5 SelectMenu_RestoreFlags puts g_gameFlags 0xC000 back while the curtain is still drawn
    SEL_CLOSE_TAIL = 6,  // curtain shrinking again in 0x542759; at the end sets g_gameFlags |= 0x4000 and returns to SEL_CLOSED. ~18 frames
    SEL_SUPPRESSED = 7,  // sentinel checked by Map_Open / SelectMenu_RestoreFlags / Game_Frame_2 to mean 'do not touch the map'
};

// u8 return code shared by the list selectors D3DApp_StepDevice 0x404c9b, D3DApp_SetDeviceIndex 0x404d77, D3DApp_StepMode 0x404dcf, D3DApp_SetModeIndex 0x404e86, D3DApp_StepJoystick 0x405b79, D3DApp_SetJoystickIndex 0x405c11, SoundDevice_StepDevice 0x406747 and SoundDevice_SetDeviceIndex 0x4067dc. The launcher loops on Step*(1) until it returns 2.
enum SelectResult {
    SEL_OK = 0,  // Index moved or set.
    SEL_CLAMPED_AT_START = 1,  // Backward step went below 0 and was clamped. It exists in all four Step functions but is dead code: the index is unsigned (DWORD jae / zero-extended byte jge), so the test never fires and the index wraps instead.
    SEL_CLAMPED_AT_END = 2,  // Forward step passed the last entry; the index is clamped to count-1.
    SEL_OUT_OF_RANGE = 3,  // Set*Index got an index >= count; state unchanged.
};

