// SoundChannel.playFlags (+0xc) = Sound_Play's 4th argument
enum SoundPlayFlags {
    SNDF_LOOP = 0x01,  // Sound_Play sets StaticSound.looping (also forced by SndBankEntry.loop == 1)
    SNDF_POSITIONAL = 0x02,  // Sound_UpdateChannelGain attenuates by distance from owner+0xc/+0xe/+0x10 to g_camPos
    SNDF_DIST_HORIZONTAL = 0x04,  // distance uses x and z only (vertical ignored)
    SNDF_NO_RETRIGGER = 0x08,  // Sound_Play returns the existing handle if the same owner already has this soundId active; the default Load_SND gives every channel
    SNDF_NO_ATTENUATION = 0x10,  // overrides SNDF_POSITIONAL (distance gain stays 1.0)
};

// Byte offsets of the 15 virtual methods shared by g_vtblStaticSound 0x574458 and g_vtblStreamSound 0x57449C (the abstract base 0x57441C declares all of them pure except the destructor). Useful because the module calls its own methods through `*(code **)(*this + N)` and the decompiler shows only the raw offset.
enum SoundVMethod {
    SOUNDV_DTOR = 0x00,  // Scalar deleting destructor (flags & 1 => operator delete).
    SOUNDV_CREATE_FROM_WAVE = 0x04,  // Create the buffer from a caller-owned WaveFile.
    SOUNDV_CREATE_FROM_FILE = 0x08,  // Open a .WAV path and create the buffer; the object owns the WaveFile.
    SOUNDV_FREE = 0x0c,  // Release the buffer, the notify interface and any owned WaveFile.
    SOUNDV_RESTORE = 0x10,  // Restore a lost buffer and refill it. Called by Play.
    SOUNDV_PLAY = 0x14,  // Start playback. Pure on StreamSound - use StreamSound_Play 0x421230 instead.
    SOUNDV_STOP = 0x18,  // Stop and rewind to 0.
    SOUNDV_SET_PAUSED = 0x1c,  // (char bPause) Stop without rewinding, or resume.
    SOUNDV_REWIND = 0x20,  // SetCurrentPosition(0). Same function 0x420A40 in both tables.
    SOUNDV_SET_POSITION = 0x24,  // (float frac01) Seek to a fraction of the buffer. Same function 0x4212E0 in both tables.
    SOUNDV_IS_PLAYING = 0x28,  // BOOL. StaticSound asks DirectSound; StreamSound reads its own `stopped` flag.
    SOUNDV_SET_VOLUME = 0x2c,  // (float gain01) Same function 0x420A80 in both tables.
    SOUNDV_SET_PAN = 0x30,  // (float pan) Same function 0x421390 in both tables.
    SOUNDV_SET_FREQUENCY = 0x34,  // (DWORD hz) Same function 0x420AF0 in both tables.
    SOUNDV_FILL_BUFFER = 0x38,  // Refill the buffer from the start of the wave data.
};

// Last argument of Sprite_Draw (0x53a7f7) and AnimSprite_Draw (0x53b67e); both implement the identical switch. Selects a permutation of the four screen corners and a rotation index 0..3 applied to the four UV pairs. Value set {0,1,2,3,4,8,0xC} read from the switch cases in 0x53a7f7 (verified). The rotation cases pivot about the quad CENTRE: the divisor at 0x574320 is 2.0f (exe bytes 00 00 00 40), so they are rotations, not diamonds built from the rect midpoints.
enum SpriteFlipMode {
    SPRFLIP_NONE = 0,  // default: axis-aligned quad, UV rotation 0
    SPRFLIP_ROT90 = 1,  // quad rotated 90 degrees about its centre, UV rotation index 1. Handedness (CW vs CCW on a y-down screen) not checked.
    SPRFLIP_UV_ROT180 = 2,  // UV rotation index 2 only - the geometry is identical to SPRFLIP_NONE (case 2 sets only the UV index), so this is a 180-degree rotation of the texture within a fixed quad
    SPRFLIP_ROT270 = 3,  // quad rotated about its centre the opposite way from mode 1, UV rotation index 3
    SPRFLIP_MIRROR_X = 4,  // x0/x1 swapped, UV rotation 0
    SPRFLIP_MIRROR_Y = 8,  // y0/y1 swapped, UV rotation 0
    SPRFLIP_MIRROR_XY = 0xc,  // both axes swapped, UV rotation 0
};

