// texture page format word (PolyBatcher::LoadTexturePages; bits 2-4 are a field)
enum TexPageFormat {
    TEXFMT_PIXEL_MASK = 0x3,  // LoadTexturePages: format & 3 is the page's TextureFormat, passed to the Texture constructor
    TEXFMT_KIND_IMMEDIATE = 0x4,  // (format & TEXFMT_KIND_MASK) == 4: an immediate page with its own batch (the file lists these first); state flags DITHER | TEXTURED | FILTER_LINEAR
    TEXFMT_KIND_BLEND = 0x8,  // a sorted page drawn alpha-blended: state flags BLEND_ALPHA | TEXTURED | FILTER_LINEAR
    TEXFMT_KIND_ADD = 0x10,  // a sorted page drawn additively: state flags BLEND_ADD | TEXTURED | FILTER_LINEAR; any other kind after the immediate pages makes LoadTexturePages return 0
    TEXFMT_KIND_MASK = 0x1c,  // LoadTexturePages: switch (format & 0x1c), == 4 is immediate
};

// The `align` byte threaded through Text_Printf / Text_PrintfStyled / Menu_Printf down to the glyph emitter at 0x535F03, where it selects the starting pen X for each line.
enum TextAlign {
    TEXTALIGN_CONTINUE = 0,  // start at the current g_textCursorX (continue after the previous text)
    TEXTALIGN_LEFT = 1,  // start at window X = 0
    TEXTALIGN_CENTER = 2,  // (windowW - lineChars * glyphWidth) / 2
    TEXTALIGN_RIGHT = 3,  // windowW - lineChars * glyphWidth
};

// single-byte control codes embedded in a formatted text buffer by the engine's printf 0x53495F and interpreted by every emitter (0x535F03, 0x535A88, 0x53618C, 0x5346FF, 0x533403, 0x533EC3, 0x533DDA)
enum TextCtrlCode {
    TXT_COLOR = 0x01,  // inline colour: the next THREE bytes are the 24-bit RGB (little-endian b,g,r as assembled by 0x535A88: b + g*0x100 + r*0x10000) written straight into Font.color. Contributes nothing to the measured width and is skipped by every scanner
    TXT_NEWLINE = 0x0A,  // cursorX = 0, cursorY += Font.lineHeight
    TXT_SPACE = 0x20,  // advance one Font.glyphWidth without emitting a quad; also the word-break character for the wrap scanner 0x5346FF
    TXT_END = 0x00,  // terminator
};

// '$NAME$' escapes recognised by the engine printf 0x53495F. The name is copied into the scratch buffer at 0x6ddb10 and dispatched on its FIRST character only
enum TextEscapeKind {
    ESC_B_BUTTON = 0x42,  // 'B' - $B_CROSS$, $B_SQUARE$, $B_TRIANGLE$, $B_CIRCLE$, $B_L1$, $B_L2$, $B_R1$, $B_R2$, $B_SELECT$, $B_START$, $B_UP$, $B_DOWN$, $B_LEFT$, $B_RIGHT$, $B_VALID$, $B_CANCEL$, $B_ACTION$, $B_JUMP$, $B_RUN$, $B_SNEAK$, $B_INTVIEW$, $B_QUICKINV$, $B_CAM_LEFT$, $B_CAM_RIGHT$. Handled by 0x533FBD, which looks the name up in the alphabetically sorted table of 24 button names at 0x57bce4..0x57bd9b and emits the matching glyph code
    ESC_C_COLOR = 0x43,  // 'C' - $C_DEFAULT$, $C_WHITE$, $C_RED$, $C_GREEN$, $C_BLUE$, $C_YELLOW$, $C_CYAN$, $C_PURPLE$ (names at 0x57bf70..0x57c007, present twice). Handled by 0x53447C, which emits the 4-byte TXT_COLOR sequence. Text_MeasureLine 0x533403 subtracts 1 from its width count for this escape specifically
    ESC_G_NAME = 0x47,  // 'G' - $G_NAME$ (0x57bf60), the player/save name. Handled by 0x5343DA, which expands it from the UI string bank
    ESC_M_CARD = 0x4D,  // 'M' - $M_CARD$ (0x57bf68), the memory-card/save-slot label. Handled by 0x534CD0, which calls through the function pointer at 0x6e3898 with 0x32
};

// Text_PageStep mode (engine/text.cpp 0x5328b3 family)
enum TextPageStep {
    TEXTPAGE_SKIP_BLANK = 0x0,  // mode 0 moves on only when the current line is blank
    TEXTPAGE_PREV = 0x1,  // mode 1 goes to the previous page mark
    TEXTPAGE_NEXT = 0x2,  // mode 2 goes to the next page mark
};

// Texture format / g_texRequestedFormat (engine/texture.cpp)
enum TextureFormat {
    TEXFMT_RGB565 = 0x0,  // g_texRequestedFormat 0 accepts rBits 5 / gBits 6; format 0 copies 16-bit pixels unchanged
    TEXFMT_ARGB1555 = 0x1,  // 1 accepts 5/5 bits with an alpha mask; format 1 repacks 565 -> 1555
    TEXFMT_ARGB4444 = 0x2,  // 2 accepts 4/4 bits with an alpha mask; format 2 repacks to 4444 (HoleFX mask texture doc: format-2 = ARGB4444)
};

// Texture::Texture *result codes (engine/texture.cpp)
enum TextureResult {
    TEXRES_OK = 0x0,  // the constructors end with *result = 0
    TEXRES_NO_DEVICE = 0x1,  // *result = 1 when !app->deviceReady
    TEXRES_NO_BITMAP = 0x2,  // *result = 2 when LoadImage returned NULL (file constructor)
    TEXRES_NO_PIXEL_FORMAT = 0x3,  // *result = 3 when no DDPIXELFORMAT matched (dwRGBBitCount == 0) or the format is unknown (default:)
    TEXRES_OUT_OF_MEMORY = 0x4,  // *result = 4 after CreateSurface returned DDERR_OUTOFVIDEOMEMORY / E_OUTOFMEMORY
    TEXRES_GDI_FAILED = 0x5,  // *result = 5 when CreateCompatibleDC / GetDC failed
};

