// WAR table entry type byte (entry >> 24)
enum WarResType {
    WAR_RES_IGNORED_1 = 0x1,  // GetResourceType: types 1/2 are class 4 (ignored)
    WAR_RES_IGNORED_2 = 0x2,  // types 1/2 ignored
    WAR_RES_MESH = 0x3,  // type 3: world mesh (InstMode INST_MODE_WAR_STATIC)
    WAR_RES_MODEL = 0x4,  // type 4: animated model (INST_MODE_WAR_ANIMATED)
    WAR_RES_SCENARIC = 0x5,  // type 5: scenaric object record (class 1)
    WAR_RES_TYPE_8 = 0x8,  // class 3 (content undecoded) (inferred)
    WAR_RES_TYPE_9 = 0x9,  // class 3 (content undecoded) (inferred)
    WAR_RES_CINEMATIC = 0xa,  // type 0xA: cinematic (class 2)
    WAR_RES_MESH_B = 0xb,  // type 0xB: world mesh (INST_MODE_WAR_STATIC_0B)
    WAR_RES_SKY = 0x26,  // type 0x26: sky mesh (INST_MODE_WAR_SKY)
    WAR_RES_TYPE_27 = 0x27,  // class 3 (content undecoded) (inferred)
    WAR_RES_UNCOUNTED = 0x40,  // type bit: Load_WAR 0x549d25 does not count a mesh or model resource that has it (a scenaric record is counted anyway); GetResourceType 0x547470 gives any unlisted type with it class 3 (data); WAR_RES_TYPE_MASK strips it
    WAR_RES_COLL_GRID = 0x80,  // 0x80: collision grid (Install_WarResource)
    WAR_RES_COLL_TRIS = 0x81,  // 0x81: collision triangles
    WAR_RES_EXPORTS = 0x82,  // 0x82: export table
    WAR_RES_HEADER3 = 0x83,  // 0x83: three-u32 header (0x6ddf60/64/68)
    WAR_RES_OBJ_GRID = 0x84,  // 0x84: object/cluster grid -> ObjGrid_Init
    WAR_RES_PAIRS = 0x85,  // 0x85: {count; pair[2][]} relocated
    WAR_RES_ANIM_NAMES = 0x86,  // 0x86: model/animation debug-name table (g_animNameTable 0x585050)
    WAR_RES_TYPE_MASK = 0xbf,  // (entry >> 24) & 0xbf in Load_WAR, BsFile::First/NextFrame, Res_ModelType, Instance_InitFromWarRecord
};

