// u32 at descriptor+4. Evidence = the reader quoted.
enum WolfStateFlags {
    WSF_LOOP_ANIM = 0x00000001,  // Wolf_SetState passes flags&1 as the loop argument
    WSF_STATIONARY = 0x00000002,  // Set on standing/idle stances; msg 0x403 returns 1 only if neither 0x2 nor 0x4 (inferred meaning)
    WSF_BUSY_OR_QUIET = 0x00000004,  // Falls, sneaks, pick-ups; part of mask 0x8c004 that stops Wolf_SwapHeldItem from changing state; msg 0x403 (inferred meaning)
    WSF_SLIDING = 0x00000008,  // Wolf_Update does not reset the slope timer +0xc4 (slide states 9,0x67,0x8b,0xbb)
    WSF_CAM_LEDGE_PROBE = 0x00000010,  // Wolf::UpdateCamera: (stateD->flags & 0x10) && !(flags & 0x20) -> g_camReqFlags.ledgeProbe = 1 (verified)
    WSF_NO_DISTANCE_COUNT = 0x00000020,  // Wolf_MoveWithPlatform does not add to travelled distance +0x6d4; trail fx selector (rocket 0x54 only)
    WSF_RUN_COLLISION = 0x00000040,  // alt collision in Wolf_MoveWithPlatform; msg 0x40c 'is running'; run dust
    WSF_GROUND_STATE = 0x00000080,  // slope logic; msg 0x40e/0x427 'on ground'; footprints
    WSF_ITEM_WHEEL_OK = 0x00000100,  // quick inventory / item swap allowed
    WSF_IGNORE_INPUT_FREEZE = 0x00000200,  // msg 0xe (input freeze) ignored; object flag on enter (death/scripted)
    WSF_BODY_FLAG0 = 0x00000400,  // Wolf_EnterState -> obj+0x78 bit 0
    WSF_SKIP_BOX_TEST = 0x00000800,  // Wolf_EnterState -> obj+0x3a bit 0x400
    WSF_CAM_FIXED_PITCH = 0x00001000,  // cam mode 0: request |=4 with angle 0x200 (umbrella air states)
    WSF_CONTEXT_ACTIONS = 0x00002000,  // Wolf_ScanContextActions runs
    WSF_IN_WATER = 0x00004000,  // no water re-entry; msg 0x41f; kill type 0 -> 0x4c
    WSF_KEEP_COVER = 0x00008000,  // keeps +0x634; msg 0x404 does the line-of-sight cover test
    WSF_SHEEP_NIBBLE = 0x00010000,  // msg 1/2 from Sheep: 20 s timer +0x6d8 then bush lost (state 0x64 only)
    WSF_KEEP_ELASTIC = 0x00020000,  // Wolf_EnterState / Wolf_DropHeld keep +0x668 link (0x72,0x73)
    WSF_ITEM_IN_USE = 0x00040000,  // held item gets the in-use message on enter; blocks swap (mask 0x2040000)
    WSF_AIRBORNE = 0x00080000,  // forces Wolf_IsFalling
    WSF_LOOK_MODE_OK = 0x00100000,  // first-person look allowed
    WSF_WATER_COLLIDE = 0x00200000,  // 0x486c1b uses sweep 0x511a12 (0x43,0x44,0x4c)
    WSF_CAM_USE_WOLF_ANGLE = 0x00400000,  // cam mode 0: request |=4 with wolf rot (0x44 swim)
    WSF_ICE_BLOCK = 0x00800000,  // attach ice-block model on enter / detach on leave; grab->0x4d, release->0x4b, geyser->0xdb
    WSF_INTERACTING = 0x01000000,  // passed to platform-push routine 0x49205d (arg 4); interaction states
    WSF_UNTOUCHABLE = 0x02000000,  // kill msg 0, catch 0x400/0x419 and most reaction messages refused; blocks item swap
    WSF_MAGNET_DRAG = 0x04000000,  // 0xc8/0xc9; part of msg 0x53 refuse mask 0x26084000
    WSF_FLATTENED = 0x08000000,  // msg 0x41c query; enables 0x41d; refuses 0x41b
    WSF_FLYING = 0x10000000,  // msg 0x41e query (updraft, black hole, rocket)
    WSF_GHOST_CAPTURED = 0x20000000,  // msg 0x420 query (0xda)
    WSF_SMOKE_TRAIL = 0x40000000,  // Wolf_UpdateTrailFx first selector (0x1c, 0xcf)
    WSF_KILL_WHEN_DEAD = 0x80000000,  // death zones and kill msg still processed although dead flag set (0xf, 0xa9)
};

// Wolf.surface (+0x70f): the ground Ralph is on, which selects the per-surface tuning row (WolfMoveBank.surfaceTuning) and movement profile table (WolfMoveBank.profiles); Wolf::Update sets it from the ice zones (verified)
enum WolfSurface {
    WOLF_SURFACE_NORMAL = 0x0,  // normal ground
    WOLF_SURFACE_ICE = 0x1,  // inside an ICEBOX zone
};

// state field of WolfTrap
enum WolfTrapState {
    WOLFTRAP_ST_ARMED = 0x0,  // SetState 0: at home, shadow on, anim TRAP3 (inferred)
    WOLFTRAP_ST_CAUGHT = 0x1,  // SetState 1: anim TRAP0, msg 0x33 arg 1 to the victim, Sam and Bell; Update: struggle counting (inferred)
    WOLFTRAP_ST_RELEASE = 0x2,  // SetState 2: anim TRAP2, msg 0x33 arg 0, 0x1400 ms; Update: -> 0 (inferred)
    WOLFTRAP_ST_CATCHING = 0x3,  // Update 3: -> 1 once the victim is frozen (inferred)
};

// WoodenLift.liftFlags (+0x5d)
enum WoodenLiftFlags {
    WLIFT_ACTIVE = 0x1,  // set by msg 0x1f, cleared by msg 0x20 or when the lift passes below cameraChangeY; arms the scripted camera
    WLIFT_CAM_RELEASED = 0x2,  // the scripted camera is not running (set after Camera_ReleaseScripted, cleared after Camera_StartScripted)
    WLIFT_SOUND_ON = 0x4,  // motor sound 0x5e playing
};

// WoodenPlatForm::GetLoad's answer 0x50b5f4, the index into WoodenPlatForm.targetY: what stands on the platform (verified in its code)
enum WoodenPlatLoad {
    WPLAT_LOAD_EMPTY = 0x0,  // nothing counted: targetY[0], the rest height (the start pos.y)
    WPLAT_LOAD_SHEEP = 0x1,  // a sheep (CLASSID_SHEEP) and no heavier object: targetY[1], halfway
    WPLAT_LOAD_HEAVY = 0x2,  // Ralph (CLASSID_WOLF) or a rock (CLASSID_ROCK), returned at once: targetY[2], -MINZVALUE
};

// WorldObj +3 drawKind: index into g_worldObjDrawFns 0x57eaf0, set by WorldObj_CreateFromResource.
enum WorldObjDrawKind {
    WORLDOBJ_HIDDEN = 0,  // WorldObj_DrawHidden: only clears INST_F_DRAWN. Written by VisibilityManager 0x5039c8 to hide a mesh.
    WORLDOBJ_STATIC = 1,  // WAR type 3 static world mesh, WorldObj_DrawStatic
    WORLDOBJ_STATIC_0B = 2,  // WAR type 0xB static world mesh, WorldObj_DrawStatic0B (identical code)
    WORLDOBJ_SKY = 3,  // WAR type 0x26 camera-centred mesh, WorldObj_DrawSky (Game_Frame also calls it directly before the Z clear)
    WORLDOBJ_ANIMATED = 4,  // WAR type 4 animated world model, 0x55da1e. No retail level contains one.
};

// Water-current bits in a zone Box.flags u32, decoded by Zone_GetFlowVelocity 0x5112d6 and Zone_GetFlowHeading 0x5113fa.
enum ZoneFlowFlags {
    FLOW_SLOW = 0x00800000,  // speed 100 (takes priority over FAST)
    FLOW_FAST = 0x04000000,  // speed 400 (default speed 200 when neither is set)
    FLOW_NEG_X = 0x08000000,  // current toward -x (heading 0x400)
    FLOW_POS_X = 0x10000000,  // current toward +x (heading 0xc00); checked before NEG_X
    FLOW_NEG_Z = 0x20000000,  // current toward -z (heading 0)
    FLOW_POS_Z = 0x40000000,  // current toward +z (heading 0x800); checked before NEG_Z
};

// 
enum ZoneType {
    ZONE_WATER = 0x0,  // Zones_ResolveGlobalLists: list 0 <- GameRes 54 WAR_IDO_WATERBOX (s_zoneIds = {54,10,92,104,123,173,202})
    ZONE_DEATH = 0x1,  // list 1 <- 10 WAR_IDO_DEATHBOX (g_deathBoxes)
    ZONE_ICE = 0x2,  // list 2 <- 92 WAR_IDO_ICEBOX
    ZONE_SLIDE = 0x3,  // list 3 <- 104 WAR_IDO_SLIDEBOX (Wolf flags IN_SLIDE_ZONE)
    ZONE_PRINTS = 0x4,  // list 4 <- 123 WAR_IDO_PRINTSBOX (footprint zone)
    ZONE_GRAVITY = 0x5,  // list 5 <- 173 WAR_IDO_GRAVITYBOX (Wolf updraftZone)
    ZONE_SHADOW = 0x6,  // list 6 <- 202 WAR_IDO_SHADOWBOX
};

// Box.flags of a water zone (Zones_Get(ZONE_WATER), wolf waterZone)
enum ZoneWaterFlags {
    ZONE_WATER_FREEZING = 0x1000000,  // Wolf::WaterSinkStep: stopped in a 0x1000000 zone -> DropHeld + frozen float; Sheep_Update -> SHEEP_ST_FROZEN_FLOAT (docs: freezing water)
    ZONE_WATER_NO_SURFACE = 0x2000000,  // Wolf_WaterCommon: 0x2000000 -> plunge/sink state 0x49; FROZEN_FALL instead of FROZEN_FLOAT; Weather::DrawRain skips the splash (inferred)
};

// no model with an animation table for class balance in any level
enum balanceAnim {
    BALANCE_ANIM_PRESS = 0x2,  // no animation table for this class in the retail levels; named from the state that starts it (inferred)
    BALANCE_ANIM_RELEASE = 0x4,  // no animation table for this class in the retail levels; named from the state that starts it (inferred)
};

